import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const _=JSON.parse('{"title":"网盘","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/drive.md","filePath":"guide/misskey/drive.md","lastUpdated":1789295632000}'),r={name:"guide/misskey/drive.md"};function o(s,a,n,d,h,u){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="网盘" tabindex="-1">网盘 <a class="header-anchor" href="#网盘" aria-label="Permalink to &quot;网盘&quot;">​</a></h1><p>网盘（Drive）是你个人的文件管理中心，发帖上传的图片、视频等文件都会保存在这里，可重复使用。</p><h2 id="管理文件" tabindex="-1">管理文件 <a class="header-anchor" href="#管理文件" aria-label="Permalink to &quot;管理文件&quot;">​</a></h2><ul><li>通过侧栏「网盘」进入，可新建文件夹、移动、重命名、删除文件。</li><li>点击文件可查看详情：文件信息、引用了该文件的帖子等。</li><li>可以设置文件的<strong>敏感内容</strong>标记，标记后在时间线中默认折叠显示。</li><li>单个文件可以在不同帖子中重复引用，删除文件会使相关帖子中的显示失效，请谨慎操作。</li></ul><h2 id="图片装饰" tabindex="-1">图片装饰 <a class="header-anchor" href="#图片装饰" aria-label="Permalink to &quot;图片装饰&quot;">​</a></h2><p>网盘内置图片编辑能力：</p><ul><li><strong>添加边框</strong>：为图片加边框和元数据标签，装饰图片。</li><li><strong>添加水印</strong>：给图片叠加水印。</li></ul><h2 id="容量与清理" tabindex="-1">容量与清理 <a class="header-anchor" href="#容量与清理" aria-label="Permalink to &quot;容量与清理&quot;">​</a></h2><ul><li>「设置 → 网盘」可查看已用容量、设置单个文件与总容量上限。</li><li>「设置 → 网盘清理」可批量清理长时间未使用的文件。</li><li>如果出现文件下载 / 上传相关问题，可尝试改用浏览器访问网站操作。</li></ul>',9)])])}const m=e(r,[["render",o]]);export{_ as __pageData,m as default};
